/**
 * Framer Motion - Minimal Implementation for EZGalaxy
 */
(function(global) {
    'use strict';

    // Animation defaults
    const defaultTransition = {
        duration: 0.3,
        ease: 'easeOut'
    };

    // Easing functions
    const easings = {
        linear: t => t,
        easeIn: t => t * t,
        easeOut: t => t * (2 - t),
        easeInOut: t => t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t
    };

    // Convert motion props to CSS
    function getTransformString(props) {
        const transforms = [];
        if (props.x !== undefined) transforms.push(`translateX(${props.x}px)`);
        if (props.y !== undefined) transforms.push(`translateY(${props.y}px)`);
        if (props.scale !== undefined) transforms.push(`scale(${props.scale})`);
        if (props.scaleX !== undefined) transforms.push(`scaleX(${props.scaleX})`);
        if (props.scaleY !== undefined) transforms.push(`scaleY(${props.scaleY})`);
        if (props.rotate !== undefined) transforms.push(`rotate(${props.rotate}deg)`);
        if (props.rotateX !== undefined) transforms.push(`rotateX(${props.rotateX}deg)`);
        if (props.rotateY !== undefined) transforms.push(`rotateY(${props.rotateY}deg)`);
        if (props.skewX !== undefined) transforms.push(`skewX(${props.skewX}deg)`);
        if (props.skewY !== undefined) transforms.push(`skewY(${props.skewY}deg)`);
        return transforms.length ? transforms.join(' ') : '';
    }

    // Apply animation props to element
    function applyMotionProps(element, props, transition = {}) {
        const trans = { ...defaultTransition, ...transition };
        const duration = trans.duration || 0.3;
        
        // Set transition
        element.style.transition = `all ${duration}s ${trans.ease || 'ease-out'}`;
        
        // Apply transforms
        const transform = getTransformString(props);
        if (transform) element.style.transform = transform;
        
        // Apply opacity
        if (props.opacity !== undefined) element.style.opacity = props.opacity;
        
        // Apply other CSS properties
        if (props.backgroundColor) element.style.backgroundColor = props.backgroundColor;
        if (props.color) element.style.color = props.color;
        if (props.width !== undefined) element.style.width = typeof props.width === 'number' ? `${props.width}px` : props.width;
        if (props.height !== undefined) element.style.height = typeof props.height === 'number' ? `${props.height}px` : props.height;
    }

    // Create motion component
    function createMotionComponent(tag) {
        return function MotionComponent(props) {
            const {
                initial,
                animate,
                exit,
                whileHover,
                whileTap,
                whileFocus,
                whileInView,
                transition,
                variants,
                drag,
                dragConstraints,
                onDragStart,
                onDragEnd,
                onAnimationComplete,
                layout,
                layoutId,
                ...restProps
            } = props;

            // Create ref for DOM access
            const ref = React.useRef(null);
            const [isHovered, setIsHovered] = React.useState(false);
            const [isTapped, setIsTapped] = React.useState(false);

            // Apply animations on mount and updates
            React.useEffect(() => {
                const el = ref.current;
                if (!el) return;

                // Apply initial state immediately (no transition)
                if (initial) {
                    el.style.transition = 'none';
                    applyMotionProps(el, typeof initial === 'string' ? (variants?.[initial] || {}) : initial);
                    // Force reflow
                    el.offsetHeight;
                }

                // Apply animate state with transition
                if (animate) {
                    requestAnimationFrame(() => {
                        const animateProps = typeof animate === 'string' ? (variants?.[animate] || {}) : animate;
                        applyMotionProps(el, animateProps, transition);
                    });
                }
            }, [animate, initial, variants]);

            // Setup event handlers
            const handleMouseEnter = React.useCallback((e) => {
                setIsHovered(true);
                if (whileHover && ref.current) {
                    applyMotionProps(ref.current, whileHover, transition);
                }
                if (restProps.onMouseEnter) restProps.onMouseEnter(e);
            }, [whileHover, transition]);

            const handleMouseLeave = React.useCallback((e) => {
                setIsHovered(false);
                if (whileHover && ref.current && animate) {
                    const animateProps = typeof animate === 'string' ? (variants?.[animate] || {}) : animate;
                    applyMotionProps(ref.current, animateProps, transition);
                }
                if (restProps.onMouseLeave) restProps.onMouseLeave(e);
            }, [whileHover, animate, variants, transition]);

            const handleMouseDown = React.useCallback((e) => {
                setIsTapped(true);
                if (whileTap && ref.current) {
                    applyMotionProps(ref.current, whileTap, { duration: 0.1 });
                }
                if (restProps.onMouseDown) restProps.onMouseDown(e);
            }, [whileTap]);

            const handleMouseUp = React.useCallback((e) => {
                setIsTapped(false);
                if (whileTap && ref.current) {
                    const targetProps = isHovered && whileHover ? whileHover : 
                        (typeof animate === 'string' ? (variants?.[animate] || {}) : animate) || {};
                    applyMotionProps(ref.current, targetProps, { duration: 0.1 });
                }
                if (restProps.onMouseUp) restProps.onMouseUp(e);
            }, [whileTap, whileHover, animate, variants, isHovered]);

            // Merge refs
            const mergedRef = React.useCallback((node) => {
                ref.current = node;
                if (typeof restProps.ref === 'function') {
                    restProps.ref(node);
                } else if (restProps.ref) {
                    restProps.ref.current = node;
                }
            }, [restProps.ref]);

            // Build final props
            const finalProps = {
                ...restProps,
                ref: mergedRef
            };

            // Add hover/tap handlers if needed
            if (whileHover) {
                finalProps.onMouseEnter = handleMouseEnter;
                finalProps.onMouseLeave = handleMouseLeave;
            }
            if (whileTap) {
                finalProps.onMouseDown = handleMouseDown;
                finalProps.onMouseUp = handleMouseUp;
            }

            return React.createElement(tag, finalProps);
        };
    }

    // Motion object with all HTML elements
    const motion = new Proxy({}, {
        get(target, prop) {
            if (typeof prop === 'string') {
                if (!target[prop]) {
                    target[prop] = createMotionComponent(prop);
                }
                return target[prop];
            }
            return undefined;
        }
    });

    // AnimatePresence component
    function AnimatePresence({ children, mode = 'sync', initial = true, onExitComplete }) {
        // Simplified: just render children
        // Full implementation would handle exit animations
        return children;
    }

    // useAnimation hook
    function useAnimation() {
        const controls = React.useRef({
            start: (props) => Promise.resolve(),
            stop: () => {},
            set: (props) => {}
        });
        return controls.current;
    }

    // useMotionValue hook
    function useMotionValue(initial) {
        const ref = React.useRef({
            current: initial,
            get: () => ref.current.current,
            set: (v) => { ref.current.current = v; },
            onChange: (callback) => () => {}
        });
        return ref.current;
    }

    // useTransform hook
    function useTransform(value, inputRange, outputRange) {
        return useMotionValue(outputRange[0]);
    }

    // useSpring hook
    function useSpring(value, config) {
        return useMotionValue(typeof value === 'number' ? value : value.get());
    }

    // useInView hook
    function useInView(ref, options = {}) {
        const [inView, setInView] = React.useState(false);
        
        React.useEffect(() => {
            if (!ref.current) return;
            
            const observer = new IntersectionObserver(
                ([entry]) => setInView(entry.isIntersecting),
                { threshold: options.amount || 0, ...options }
            );
            
            observer.observe(ref.current);
            return () => observer.disconnect();
        }, [ref, options.amount]);
        
        return inView;
    }

    // useScroll hook
    function useScroll(options = {}) {
        const scrollY = useMotionValue(0);
        const scrollX = useMotionValue(0);
        const scrollYProgress = useMotionValue(0);
        const scrollXProgress = useMotionValue(0);
        
        React.useEffect(() => {
            const handleScroll = () => {
                const target = options.container?.current || window;
                const scrollTop = target === window ? window.scrollY : target.scrollTop;
                const scrollLeft = target === window ? window.scrollX : target.scrollLeft;
                const scrollHeight = target === window ? 
                    document.documentElement.scrollHeight - window.innerHeight :
                    target.scrollHeight - target.clientHeight;
                const scrollWidth = target === window ?
                    document.documentElement.scrollWidth - window.innerWidth :
                    target.scrollWidth - target.clientWidth;
                
                scrollY.set(scrollTop);
                scrollX.set(scrollLeft);
                scrollYProgress.set(scrollHeight > 0 ? scrollTop / scrollHeight : 0);
                scrollXProgress.set(scrollWidth > 0 ? scrollLeft / scrollWidth : 0);
            };
            
            const target = options.container?.current || window;
            target.addEventListener('scroll', handleScroll, { passive: true });
            handleScroll();
            
            return () => target.removeEventListener('scroll', handleScroll);
        }, [options.container]);
        
        return { scrollY, scrollX, scrollYProgress, scrollXProgress };
    }

    // Export
    const FramerMotion = {
        motion,
        AnimatePresence,
        useAnimation,
        useMotionValue,
        useTransform,
        useSpring,
        useInView,
        useScroll
    };

    // Expose globally
    global.motion = motion;
    global.AnimatePresence = AnimatePresence;
    global.useAnimation = useAnimation;
    global.useMotionValue = useMotionValue;
    global.useTransform = useTransform;
    global.useSpring = useSpring;
    global.useInView = useInView;
    global.useScroll = useScroll;
    global.FramerMotion = FramerMotion;
    
    // Expose as Motion object for destructuring compatibility
    global.Motion = {
        motion,
        AnimatePresence,
        useAnimation,
        useMotionValue,
        useTransform,
        useSpring,
        useInView,
        useScroll
    };

})(typeof window !== 'undefined' ? window : this);
